# documentation: https://docs.anythingllm.com/installation-docker/overview
# slogan: AnythingLLM is the easiest to use, all-in-one AI application that can do RAG, AI Agents, and much more with no code or infrastructure headaches.
# category: ai
# tags: lowcode, nocode, llm, openai, anthropic, machine-learning, rag, agents, chatbot, api, team, bot
# logo: svgs/anythingllm.svg
# port: 3001

services:
  anything-llm:
    image: mintplexlabs/anythingllm
    environment:
      - SERVICE_URL_ANYTHINGLLM_3001
      - STORAGE_DIR=/app/server/storage
      - DISABLE_TELEMETRY=${DISABLE_TELEMETRY:-true}
      - PASSWORDLOWERCASE=${PASSWORDLOWERCASE:-1}
      - PASSWORDMAXCHAR=${PASSWORDMAXCHAR:-250}
      - PASSWORDMINCHAR=${PASSWORDMINCHAR:-6}
      - PASSWORDNUMERIC=${PASSWORDNUMERIC:-1}
      - PASSWORDREQUIREMENTS=${PASSWORDREQUIREMENTS:-1}
      - PASSWORDSYMBOL=${PASSWORDSYMBOL:-1}
      - PASSWORDUPPERCASE=${PASSWORDUPPERCASE:-1}
      - SIG_KEY=${SERVICE_PASSWORD_SIGKEY}
      - SIG_SALT=${SERVICE_PASSWORD_SIGSALT}
      - JWT_SECRET=${SERVICE_PASSWORD_JWTSECRET}
      - AUTH_TOKEN=${SERVICE_PASSWORD_AUTHTOKEN}
      - SERVER_PORT=${SERVER_PORT:-3001}
      - VECTOR_DB=lancedb
    cap_add:
      - SYS_ADMIN
    volumes:
      - "anythingllm-storage:/app/server/storage"
      - "anythingllm-hot:/app/collector/hotdir"
      - "anythingllm-outputs:/app/collector/outputs"
    user: "${UID:-1000}:${GID:-1000}"

volumes:
  anythingllm-storage:
  anythingllm-hot:
  anythingllm-outputs:

# documentation: https://github.com/dgtlmoon/changedetection.io/
# slogan: Website change detection monitor and notifications.
# category: monitoring
# tags: web, alert, monitor
# logo: svgs/changedetection.png
# port: 5000

services:
  changedetection:
    image: ghcr.io/dgtlmoon/changedetection.io
    volumes:
      - changedetection-data:/datastore
    environment:
      - SERVICE_URL_CHANGEDETECTION_5000
      - BASE_URL=${SERVICE_URL_CHANGEDETECTION}
      - PUID=${PUID:-1000}
      - PGID=${PGID:-1000}
      - PLAYWRIGHT_DRIVER_URL=${PLAYWRIGHT_DRIVER_URL:-ws://browser-sockpuppet-chrome:3000}
      - HIDE_REFERER=${HIDE_REFERER:-true}
      - FETCH_WORKERS=${FETCH_WORKERS:-10}
      - MINIMUM_SECONDS_RECHECK_TIME=${MINIMUM_SECONDS_RECHECK_TIME:-3}
      - DISABLE_VERSION_CHECK=${DISABLE_VERSION_CHECK:-true}
      - SCREENSHOT_MAX_HEIGHT=${SCREENSHOT_MAX_HEIGHT:-16000}
      - TZ=${TZ:-UTC}
      - LOGGER_LEVEL=${LOGGER_LEVEL:-DEBUG}
    healthcheck:
      test: ["CMD", "echo", "ok"]
      interval: 5s
      timeout: 20s
      retries: 10
    depends_on:
      browser-sockpuppet-chrome:
        condition: service_started

  browser-sockpuppet-chrome:
    hostname: browser-sockpuppet-chrome
    image: dgtlmoon/sockpuppetbrowser:latest
    cap_add:
      - SYS_ADMIN
    environment:
      - SCREEN_WIDTH=${SCREEN_WIDTH:-1920}
      - SCREEN_HEIGHT=${SCREEN_HEIGHT:-1024}
      - SCREEN_DEPTH=${SCREEN_DEPTH:-16}
      - MAX_CONCURRENT_CHROME_PROCESSES=${MAX_CONCURRENT_CHROME_PROCESSES:-10}
    healthcheck:
      test: ["CMD", "echo", "ok"]
      interval: 5s
      timeout: 20s
      retries: 10

volumes:
  changedetection-data:

# documentation: https://www.chatwoot.com/docs/self-hosted/
# slogan: Delightful customer relationships at scale.
# category: helpdesk
# tags: chatwoot,chat,api,open,source,rails,redis,postgresql,sidekiq
# logo: svgs/chatwoot.svg
# port: 3000

services:
  chatwoot:
    image: chatwoot/chatwoot:latest
    depends_on:
      - postgres
      - redis
    environment:
      - SERVICE_URL_CHATWOOT_3000
      - SECRET_KEY_BASE=$SERVICE_PASSWORD_CHATWOOT
      - FRONTEND_URL=${SERVICE_URL_CHATWOOT}
      - DEFAULT_LOCALE=${CHATWOOT_DEFAULT_LOCALE}
      - FORCE_SSL=${FORCE_SSL:-false}
      - ENABLE_ACCOUNT_SIGNUP=${ENABLE_ACCOUNT_SIGNUP:-false}
      - REDIS_URL=redis://default@redis:6379
      - REDIS_PASSWORD=$SERVICE_PASSWORD_REDIS
      - REDIS_OPENSSL_VERIFY_MODE=${REDIS_OPENSSL_VERIFY_MODE:-none}
      - POSTGRES_DATABASE=${POSTGRES_DB:-chatwoot}
      - POSTGRES_HOST=${POSTGRES_HOST:-postgres}
      - POSTGRES_USERNAME=$SERVICE_USER_POSTGRES
      - POSTGRES_PASSWORD=$SERVICE_PASSWORD_POSTGRES
      - RAILS_MAX_THREADS=${RAILS_MAX_THREADS:-5}
      - NODE_ENV=${NODE_ENV:-production}
      - RAILS_ENV=${RAILS_ENV:-production}
      - INSTALLATION_ENV=${INSTALLATION_ENV:-docker}
      - MAILER_SENDER_EMAIL=${CHATWOOT_MAILER_SENDER_EMAIL}
      - SMTP_ADDRESS=${CHATWOOT_SMTP_ADDRESS}
      - SMTP_AUTHENTICATION=${CHATWOOT_SMTP_AUTHENTICATION}
      - SMTP_DOMAIN=${CHATWOOT_SMTP_DOMAIN}
      - SMTP_ENABLE_STARTTLS_AUTO=${CHATWOOT_SMTP_ENABLE_STARTTLS_AUTO}
      - SMTP_PORT=${CHATWOOT_SMTP_PORT}
      - SMTP_USERNAME=${CHATWOOT_SMTP_USERNAME}
      - SMTP_PASSWORD=${CHATWOOT_SMTP_PASSWORD}
      - ACTIVE_STORAGE_SERVICE=${ACTIVE_STORAGE_SERVICE:-local}
      - SAFE_FETCH_ALLOW_PRIVATE_NETWORK=${SAFE_FETCH_ALLOW_PRIVATE_NETWORK:-false}
    entrypoint: docker/entrypoints/rails.sh
    command: sh -c "bundle exec rails db:chatwoot_prepare && bundle exec rails s -p 3000 -b 0.0.0.0"
    volumes:
      - rails-data:/app/storage
    healthcheck:
      test: ["CMD", "wget", "--spider", "-q", "http://127.0.0.1:3000"]
      interval: 5s
      timeout: 20s
      retries: 10

  sidekiq:
    image: chatwoot/chatwoot:latest
    depends_on:
      - postgres
      - redis
    environment:
      - SECRET_KEY_BASE=$SERVICE_PASSWORD_CHATWOOT
      - FRONTEND_URL=${SERVICE_URL_CHATWOOT}
      - DEFAULT_LOCALE=${CHATWOOT_DEFAULT_LOCALE}
      - FORCE_SSL=${FORCE_SSL:-false}
      - ENABLE_ACCOUNT_SIGNUP=${ENABLE_ACCOUNT_SIGNUP:-false}
      - REDIS_URL=redis://default@redis:6379
      - REDIS_PASSWORD=$SERVICE_PASSWORD_REDIS
      - REDIS_OPENSSL_VERIFY_MODE=${REDIS_OPENSSL_VERIFY_MODE:-none}
      - POSTGRES_DATABASE=${POSTGRES_DB:-chatwoot}
      - POSTGRES_HOST=${POSTGRES_HOST:-postgres}
      - POSTGRES_USERNAME=$SERVICE_USER_POSTGRES
      - POSTGRES_PASSWORD=$SERVICE_PASSWORD_POSTGRES
      - RAILS_MAX_THREADS=${RAILS_MAX_THREADS:-5}
      - NODE_ENV=${NODE_ENV:-production}
      - RAILS_ENV=${RAILS_ENV:-production}
      - INSTALLATION_ENV=${INSTALLATION_ENV:-docker}
      - MAILER_SENDER_EMAIL=${CHATWOOT_MAILER_SENDER_EMAIL}
      - SMTP_ADDRESS=${CHATWOOT_SMTP_ADDRESS}
      - SMTP_AUTHENTICATION=${CHATWOOT_SMTP_AUTHENTICATION}
      - SMTP_DOMAIN=${CHATWOOT_SMTP_DOMAIN}
      - SMTP_ENABLE_STARTTLS_AUTO=${CHATWOOT_SMTP_ENABLE_STARTTLS_AUTO}
      - SMTP_PORT=${CHATWOOT_SMTP_PORT}
      - SMTP_USERNAME=${CHATWOOT_SMTP_USERNAME}
      - SMTP_PASSWORD=${CHATWOOT_SMTP_PASSWORD}
      - ACTIVE_STORAGE_SERVICE=${ACTIVE_STORAGE_SERVICE:-local}
    command: ['bundle', 'exec', 'sidekiq', '-C', 'config/sidekiq.yml']
    volumes:
      - rails-data:/app/storage
    healthcheck:
      test: ["CMD-SHELL", "bundle exec sidekiqmon processes | grep -q 'sidekiq'"]
      interval: 30s
      timeout: 10s
      retries: 3

  postgres:
    image: pgvector/pgvector:pg12
    restart: always
    volumes:
      - postgres-data:/var/lib/postgresql/data
    environment:
      - POSTGRES_DB=${POSTGRES_DB:-chatwoot}
      - POSTGRES_USER=$SERVICE_USER_POSTGRES
      - POSTGRES_PASSWORD=$SERVICE_PASSWORD_POSTGRES
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U $SERVICE_USER_POSTGRES -d chatwoot -h 127.0.0.1"]
      interval: 30s
      timeout: 10s
      retries: 5

  redis:
    image: redis:alpine
    restart: always
    command: ["sh", "-c", "redis-server --requirepass \"$SERVICE_PASSWORD_REDIS\""]
    volumes:
      - redis-data:/data
    healthcheck:
      test: ["CMD", "redis-cli", "-a", "$SERVICE_PASSWORD_REDIS", "PING"]
      interval: 30s
      timeout: 10s
      retries: 5

volumes:
  rails-data:
  postgres-data:
  redis-data:

# documentation: https://www.dolibarr.org/documentation-home.php
# slogan: Dolibarr is a modern software package to manage your organization's activity (contacts, quotes, invoices, orders, stocks, agenda, hr, expense reports, accountancy, ecm, manufacturing, ...).
# category: productivity
# tags: crm,ERP
# logo: svgs/dolibarr.png
# port: 80

services:
  dolibarr:
    image: dolibarr/dolibarr:latest
    environment:
      - SERVICE_URL_DOLIBARR_80
      - WWW_USER_ID=${WWW_USER_ID:-1000}
      - WWW_GROUP_ID=${WWW_GROUP_ID:-1000}
      - DOLI_DB_HOST=mariadb
      - DOLI_DB_NAME=${MYSQL_DATABASE:-dolibarr-db}
      - DOLI_DB_USER=${SERVICE_USER_MYSQL}
      - DOLI_DB_PASSWORD=${SERVICE_PASSWORD_MYSQL}
      - DOLI_URL_ROOT=${SERVICE_URL_DOLIBARR}
      - DOLI_ADMIN_LOGIN=${SERVICE_USER_DOLIBARR}
      - DOLI_ADMIN_PASSWORD=${SERVICE_PASSWORD_DOLIBARR}
      - DOLI_CRON=${DOLI_CRON:-0}
      - DOLI_INIT_DEMO=${DOLI_INIT_DEMO:-0}
      - DOLI_COMPANY_NAME=${DOLI_COMPANY_NAME:-MyBigCompany}
    volumes:
      - dolibarr_docs:/var/www/documents
      - dolibarr_custom:/var/www/html/custom
    healthcheck:
      test: ["CMD", "curl", "-f", "http://127.0.0.1:80"]
      interval: 2s
      timeout: 10s
      retries: 15

  mariadb:
    image: mariadb:latest
    environment:
      - MYSQL_DATABASE=${MYSQL_DATABASE:-dolibarr-db}
      - MYSQL_USER=${SERVICE_USER_MYSQL}
      - MYSQL_PASSWORD=${SERVICE_PASSWORD_MYSQL}
      - MYSQL_ROOT_PASSWORD=${SERVICE_PASSWORD_ROOT}
    volumes:
      - dolibarr_mariadb_data:/var/lib/mysql
    healthcheck:
      test: ["CMD", "healthcheck.sh", "--connect", "--innodb_initialized"]
      interval: 5s
      timeout: 20s
      retries: 10

volumes:
  dolibarr_docs:
  dolibarr_custom:
  dolibarr_mariadb_data:

