      - SQS_SECRET_ACCESS_KEY=${SQS_SECRET_ACCESS_KEY:-}
      - SQS_ACCOUNT_ID=${SQS_ACCOUNT_ID:-}
      - SQS_REGION=${SQS_REGION:-}
      - WEBSOCKET_ENABLED=${WEBSOCKET_ENABLED:-false}
      - WEBSOCKET_GLOBAL_EVENTS=${WEBSOCKET_GLOBAL_EVENTS:-false}
