services:
  grist:
    image: gristlabs/grist:latest
    environment:
      - SERVICE_URL_GRIST_8484
      - APP_HOME_URL=${SERVICE_URL_GRIST}
      - APP_DOC_URL=${SERVICE_URL_GRIST}
      - GRIST_DOMAIN=${SERVICE_FQDN_GRIST}
      - TZ=${TZ:-UTC}
      - GRIST_SUPPORT_ANON=${SUPPORT_ANON:-false}
      - GRIST_FORCE_LOGIN=${FORCE_LOGIN:-true}
      - COOKIE_MAX_AGE=${COOKIE_MAX_AGE:-86400000}
      - GRIST_PAGE_TITLE_SUFFIX=${PAGE_TITLE_SUFFIX:- - Suffix}
      - GRIST_HIDE_UI_ELEMENTS=${HIDE_UI_ELEMENTS:-billing,sendToDrive,supportGrist,multiAccounts,tutorials}
      - GRIST_UI_FEATURES=${UI_FEATURES:-helpCenter,billing,templates,createSite,multiSite,sendToDrive,tutorials,supportGrist}
      - GRIST_DEFAULT_EMAIL=${DEFAULT_EMAIL:-?}
      - GRIST_ORG_IN_PATH=${ORG_IN_PATH:-true}
      - GRIST_OIDC_SP_HOST=${SERVICE_URL_GRIST}
      - GRIST_OIDC_IDP_SCOPES=${OIDC_IDP_SCOPES:-openid profile email}
      - GRIST_OIDC_IDP_SKIP_END_SESSION_ENDPOINT=${OIDC_IDP_SKIP_END_SESSION_ENDPOINT:-false}
      - GRIST_OIDC_IDP_ISSUER=${OIDC_IDP_ISSUER:?}
      - GRIST_OIDC_IDP_CLIENT_ID=${OIDC_IDP_CLIENT_ID:?}
      - GRIST_OIDC_IDP_CLIENT_SECRET=${OIDC_IDP_CLIENT_SECRET:?}
      - GRIST_SESSION_SECRET=${SERVICE_REALBASE64_128}
      - GRIST_HOME_INCLUDE_STATIC=${HOME_INCLUDE_STATIC:-true}
      - GRIST_SANDBOX_FLAVOR=${SANDBOX_FLAVOR:-gvisor}
      - ALLOWED_WEBHOOK_DOMAINS=${ALLOWED_WEBHOOK_DOMAINS}
      - COMMENTS=${COMMENTS:-true}
      - TYPEORM_TYPE=${TYPEORM_TYPE:-postgres}
      - TYPEORM_DATABASE=${POSTGRES_DATABASE:-grist-db}
      - TYPEORM_USERNAME=${SERVICE_USER_POSTGRES}
      - TYPEORM_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
      - TYPEORM_HOST=${TYPEORM_HOST:-postgres}
      - TYPEORM_PORT=${TYPEORM_PORT:-5432}
      - TYPEORM_LOGGING=${TYPEORM_LOGGING:-false}
      - REDIS_URL=${REDIS_URL:-redis://redis:6379}
      - GRIST_HELP_CENTER=${SERVICE_URL_GRIST}/help
      - GRIST_TERMS_OF_SERVICE_URL=${SERVICE_URL_GRIST}/terms
      - FREE_COACHING_CALL_URL=${FREE_COACHING_CALL_URL}
      - GRIST_CONTACT_SUPPORT_URL=${CONTACT_SUPPORT_URL}
    volumes:
      - grist-data:/persist
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
    healthcheck:
      test:
        - CMD
        - node
        - "-e"
        - "require('http').get('http://localhost:8484/status', res => process.exit(res.statusCode === 200 ? 0 : 1))"
        - "> /dev/null 2>&1"
      interval: 5s
      timeout: 20s
      retries: 10

  postgres:
    image: postgres:16
    environment:
      - POSTGRES_DB=${POSTGRES_DATABASE:-grist-db}
      - POSTGRES_USER=${SERVICE_USER_POSTGRES}
      - POSTGRES_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
    volumes:
      - grist_postgres_data:/var/lib/postgresql/data
    healthcheck:
      test:
        - CMD-SHELL
        - "pg_isready -U $${POSTGRES_USER} -d $${POSTGRES_DB}"
      interval: 5s
      timeout: 10s
      retries: 20

  redis:
    image: redis:7
    volumes:
      - grist_redis_data:/data
    healthcheck:
      test:
        - CMD
        - redis-cli
        - PING
      interval: 5s
      timeout: 10s
      retries: 20

volumes:
  grist-data:
  grist_postgres_data:
  grist_redis_data:

# documentation: https://labelstud.io/guide/
# slogan: Label Studio is a multi-type data labeling and annotation tool with standardized output format
# category: ai
# tags: workflow, orchestration, data-pipeline, python, labelstudio, ai, elasticsearch, datasets, data, machine-learning, data-science, nlp, images, vision
# logo: svgs/labelstudio.png
# port: 8080

services:
  labelstudio:
    image: heartexlabs/label-studio:latest
    depends_on:
      postgres:
        condition: service_healthy
    environment:
      - SERVICE_URL_LABELSTUDIO_8080
      - CSRF_TRUSTED_ORIGINS=${SERVICE_URL_LABELSTUDIO}
      - EXPERIMENTAL_FEATURES=${EXPERIMENTAL_FEATURES:-false}
      - DJANGO_DB=${DJANGO_DB:-default}
      - POSTGRE_NAME=${POSTGRES_DB:-labelstudio}
      - POSTGRE_USER=${SERVICE_USER_POSTGRES}
      - POSTGRE_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
      - POSTGRE_PORT=5432
      - POSTGRE_HOST=postgres
      - LABEL_STUDIO_HOST=${SERVICE_URL_LABELSTUDIO}
      - SSRF_PROTECTION_ENABLED=${SSRF_PROTECTION_ENABLED:-true}
      - LABEL_STUDIO_DISABLE_SIGNUP_WITHOUT_LINK=${LABEL_STUDIO_DISABLE_SIGNUP_WITHOUT_LINK:-true}
      - DATA_UPLOAD_MAX_NUMBER_FILES=${DATA_UPLOAD_MAX_NUMBER_FILES:-10000}
      - LABEL_STUDIO_USERNAME=${LABEL_STUDIO_USERNAME:-admin@example.com}
      - LABEL_STUDIO_PASSWORD=${SERVICE_PASSWORD_LABELSTUDIO}
      - LABEL_STUDIO_DISABLE_SIGNUP_WITHOUT_LINK=${LABEL_STUDIO_DISABLE_SIGNUP_WITHOUT_LINK:-true}
    volumes:
      - labelstudio-data:/label-studio/data
    healthcheck:
      test: ["CMD-SHELL", "curl -f http://localhost:8080/health || exit 1"]
      interval: 5s
      timeout: 20s
      retries: 3
  postgres:
    image: postgres:16-alpine
    environment:
      - POSTGRES_USER=${SERVICE_USER_POSTGRES}
      - POSTGRES_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
      - POSTGRES_DB=${POSTGRES_DB:-labelstudio}
    volumes:
      - pg-data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -h localhost -U $${POSTGRES_USER} -d $${POSTGRES_DB}"]
      interval: 5s
      timeout: 20s
      retries: 3

volumes:
  labelstudio-data:
  pg-data:

# documentation: https://pocket-id.org/docs/setup/installation
