      - SMTP_USER=${SMTP_USER}
      - SMTP_PWD=${SMTP_PWD}
      - SMTP_TLS_ENABLED=${SMTP_TLS_ENABLED:-false}
      - BETTER_AUTH_TRUSTED_ORIGINS=${SERVICE_URL_RALLLY}
    healthcheck:
      test: ["CMD-SHELL", "bash -c ':> /dev/tcp/127.0.0.1/3000' || exit 1"]
      interval: 5s
      timeout: 20s
      retries: 10
    depends_on:
      rallly_db:
        condition: service_healthy

volumes:
  postgres-data:

